INSERT INTO `faults` (`id`, `failure_code`, `description`, `failure_analysis`, `solution`, `doc_id`, `created_at`, `updated_at`) VALUES
(1, 'E05', 'High pressure protection', '1. High pressure switch is broken\n2. Connection is loose', 'Customer service to identify the reasons', '26', NULL, '2025-06-10 17:46:07'),
(2, 'E09', 'Communication failure', '1. Signal wire connection loose\n2. There is strong magnetic field\n3. PCB is broken\n4. Signal wire is broken', 'Replace the controller communication line (mainboard COM2 port)', '28', NULL, '2025-06-10 17:46:01'),
(3, 'E12', 'Exhaust temp. too high', '1. Lack of refrigerant\n2. Fluorine system leak', 'Check then add refrigerant', '29', NULL, '2025-06-10 17:46:12'),
(4, 'E14', 'Tank temp. sensor failure', '1. Sensor failure\n2. Connection is loose', 'Replace the T4 temp. sensor', '25', NULL, '2025-06-10 17:46:19'),
(5, 'E16', 'Coil temp. sensor failure', '1. Sensor failure\n2. Connection is loose', 'Replace the T1 temp. sensor', '25', NULL, '2025-06-10 17:46:24'),
(6, 'E18', 'Exhaust temp. sensor failure', '1. Sensor failure\n2. Connection is loose', 'Replace the T3 temp. sensor', '25', NULL, '2025-06-10 17:46:28'),
(7, 'E21', 'Ambient temp. sensor failure', '1. Sensor failure\n2. Connection is loose', 'Replace the T2 temp. sensor', '25', NULL, '2025-06-10 17:46:34'),
(8, 'E29', 'Suction temp. sensor failure', '1. Sensor failure\n2. Connection is loose', 'Replace the T5 temp. sensor', '25', NULL, '2025-06-10 17:46:38');
